-- Básico: lições de vocabulário fundamental (números, cores, família, animais, etc.)
UPDATE lessons SET courseLevel = 'basico' 
WHERE LOWER(title) REGEXP 'greet|hello|number|color|colour|family|food|animal|body|clothes|weather|school|basic|alphabet|introduc|a1|a2|beginner|present simple|articles|nouns|pronouns|days|months|time|house|home|room|fruit|vegetable|drink|transport|city|country|direction|shopping|money|price|question|yes|no|please|thank';

-- Intermediário: conversação, gramática, tempos verbais
UPDATE lessons SET courseLevel = 'intermediario'
WHERE LOWER(title) REGEXP 'past|future|perfect|continuous|conditional|modal|comparison|adjective|adverb|preposition|conversation|travel|health|sport|music|movie|film|book|read|write|listen|speak|intermediate|b1|b2|phrasal|idiom|colloquial|daily routine|work|job|office|restaurant|hotel|airport|doctor|hospital|bank|post|phone|email|internet|social|media|culture|tradition|holiday|festival';

-- Avançado: fluência, expressões, literatura
UPDATE lessons SET courseLevel = 'avancado'
WHERE LOWER(title) REGEXP 'advanced|fluency|literature|poetry|debate|argumentation|rhetoric|nuance|subtle|complex|c1|c2|academic|formal|informal|register|style|idiom|expression|proverb|metaphor|irony|sarcasm|humor|satire|philosophy|history|science|politics|law|medicine|engineering';

-- Negócios/Tecnologia: vocabulário profissional
UPDATE lessons SET courseLevel = 'negocios_tecnologia'
WHERE LOWER(title) REGEXP 'business|technology|tech|professional|finance|marketing|email|meeting|presentation|startup|ai|software|hardware|programming|code|data|digital|online|e-commerce|negotiation|contract|report|proposal|project|management|leadership|strategy|investment|stock|market|economy|trade|import|export|logistics|supply|chain|hr|human resource|interview|cv|resume|salary|budget|profit|loss|revenue|customer|client|partner|vendor|supplier|b2b|b2c';

